"""Fit on nominal feature CSV and export static C99 inference for the sample MID."""

import argparse
import csv
import math
from pathlib import Path

import numpy as np
from sklearn.ensemble import IsolationForest

COLUMNS = ["seq_delta", "delta_t_ms", "packet_size", "function_code", "packets_last_second"]


def path_adjustment(count):
    if count < 2:
        return 0.0
    if count == 2:
        return 1.0
    return 2 * (math.log(count - 1) + np.euler_gamma - (count - 1) / count)


def export(model, threshold, output):
    lines = [
        "/* Generated by tools/train.py. Rebuild the app after replacing this file. */",
        "#ifndef IDS_MODEL_H",
        "#define IDS_MODEL_H",
        "#include <math.h>",
        f"#define IDS_MODEL_THRESHOLD {threshold.hex()}",
        "",
    ]

    for index, (estimator, features) in enumerate(
        zip(model.estimators_, model.estimators_features_, strict=True)
    ):
        tree = estimator.tree_
        lines.append(f"static double IDS_Tree{index}(const float *values)")

        def emit(node, depth, indent):
            left = tree.children_left[node]
            if left < 0:
                path = depth + path_adjustment(int(tree.n_node_samples[node]))
                lines.append(f"{indent}return {path.hex()};")
                return
            feature = features[tree.feature[node]]
            split = float(tree.threshold[node])
            lines.append(f"{indent}if (values[{feature}] <= {split.hex()})")
            lines.append(indent + "{")
            emit(left, depth + 1, indent + "    ")
            lines.append(indent + "}")
            emit(tree.children_right[node], depth + 1, indent)

        lines.append("{")
        if tree.node_count == 1:
            lines.append("    (void)values;")
        emit(0, 0, "    ")
        lines.extend(["}", ""])

    denominator = len(model.estimators_) * path_adjustment(model.max_samples_)
    lines.extend(["static inline double IDS_ModelScore(const float *values)", "{", "    double path = 0;"])
    lines.extend(f"    path += IDS_Tree{i}(values);" for i in range(len(model.estimators_)))
    lines.extend([f"    return pow(2.0, -path / {denominator.hex()});", "}", "#endif", ""])
    output.write_text("\n".join(lines), encoding="ascii", newline="\n")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("nominal", type=Path)
    parser.add_argument("header", type=Path)
    parser.add_argument("--reference", type=Path, help="Write held-out features and Python scores")
    args = parser.parse_args()
    with args.nominal.open(newline="", encoding="utf-8-sig") as stream:
        reader = csv.DictReader(stream)
        if reader.fieldnames != COLUMNS:
            parser.error(f"expected CSV header {','.join(COLUMNS)}")
        try:
            values = np.asarray([[float(row[col]) for col in COLUMNS] for row in reader], dtype=np.float32)
        except (TypeError, ValueError):
            parser.error("all feature columns must contain numeric values")

    if len(values) < 200 or not np.isfinite(values).all():
        parser.error("need at least 200 finite nominal records in time order")

    fit, calibration, holdout = np.split(values, [len(values) * 6 // 10, len(values) * 8 // 10])
    forest = IsolationForest(n_estimators=16, max_samples=64, random_state=42)
    forest.fit(fit)
    if not any(tree.tree_.node_count > 1 for tree in forest.estimators_):
        parser.error("nominal capture has no feature variation")
    threshold = float(np.quantile(-forest.score_samples(calibration), 0.99, method="higher"))
    scores = -forest.score_samples(holdout)
    export(forest, threshold, args.header)
    if args.reference:
        np.savetxt(args.reference, np.column_stack([holdout, scores]), delimiter=",", fmt="%.17g")

    print(f"Training/calibration/holdout: {len(fit)}/{len(calibration)}/{len(holdout)}")
    print(f"Threshold {threshold:.6f}. Nominal holdout flags: {np.count_nonzero(scores > threshold)}/{len(scores)}")


if __name__ == "__main__":
    main()
